package org.binarypasscode.image;

import android.content.Context;
import android.net.Uri;
import android.graphics.*;
import android.media.ExifInterface;
import java.io.*;

final class SecretImages {
    static final class Source{Transport.Image image;boolean alpha;int originalWidth,originalHeight;}
    static BitmapFactory.Options bounds(Context context,Uri uri)throws Exception{BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;try(InputStream in=Images.stream(context,uri)){BitmapFactory.decodeStream(in,null,opt);}if(opt.outWidth<1||opt.outHeight<1)throw Crypto.error("无法读取图片，请选择系统支持的静态PNG、JPG、BMP或WebP。");if("image/gif".equals(opt.outMimeType))throw Crypto.error("请先将GIF导出为一张静态PNG图片。");return opt;}
    static Source load(Context context,Uri uri)throws Exception{
        BitmapFactory.Options header=bounds(context,uri);int orientation=1;try(InputStream in=Images.stream(context,uri)){orientation=new ExifInterface(in).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);}catch(Exception ignored){}
        boolean swapped=orientation>=5&&orientation<=8;int ow=swapped?header.outHeight:header.outWidth,oh=swapped?header.outWidth:header.outHeight;double ratio=Math.min(1.,Math.min((ow>=oh?1920.:1080.)/ow,(ow>=oh?1080.:1920.)/oh));int targetW=Math.max(1,(int)Math.round(ow*ratio)),targetH=Math.max(1,(int)Math.round(oh*ratio)),nativeW=swapped?targetH:targetW,nativeH=swapped?targetW:targetH;
        BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.ARGB_8888;options.inScaled=false;options.inPremultiplied=false;options.inSampleSize=1;while(header.outWidth/(options.inSampleSize*2)>=nativeW&&header.outHeight/(options.inSampleSize*2)>=nativeH&&options.inSampleSize<(1<<28))options.inSampleSize*=2;
        Runtime runtime=Runtime.getRuntime();long available=runtime.maxMemory()-(runtime.totalMemory()-runtime.freeMemory());if((long)(header.outWidth/options.inSampleSize)*(header.outHeight/options.inSampleSize)*12+24*1024*1024>available)throw Crypto.error("设备可用内存不足，请关闭其他应用后重试。");
        Bitmap decoded;try(InputStream in=Images.stream(context,uri)){decoded=BitmapFactory.decodeStream(in,null,options);}if(decoded==null)throw Crypto.error("图片无法读取，格式不支持或文件已损坏。");boolean alpha=decoded.hasAlpha();int w=decoded.getWidth(),h=decoded.getHeight();int[]p=new int[w*h];try{decoded.getPixels(p,0,w,0,0,w,h);}finally{decoded.recycle();}
        if(orientation>=2&&orientation<=8){int nw=swapped?h:w,nh=swapped?w:h;int[]r=new int[p.length];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int nx=x,ny=y;switch(orientation){case 2:nx=w-1-x;break;case 3:nx=w-1-x;ny=h-1-y;break;case 4:ny=h-1-y;break;case 5:nx=y;ny=x;break;case 6:nx=h-1-y;ny=x;break;case 7:nx=h-1-y;ny=w-1-x;break;case 8:nx=y;ny=w-1-x;break;}r[ny*nw+nx]=p[y*w+x];}p=r;w=nw;h=nh;}
        if(w!=targetW||h!=targetH){Bitmap original=Bitmap.createBitmap(p,w,h,Bitmap.Config.ARGB_8888),scaled=null;try{scaled=Bitmap.createScaledBitmap(original,targetW,targetH,true);p=new int[targetW*targetH];scaled.getPixels(p,0,targetW,0,0,targetW,targetH);w=targetW;h=targetH;}finally{if(scaled!=null&&scaled!=original)scaled.recycle();original.recycle();}}
        Source source=new Source();source.image=new Transport.Image(w,h,p);source.alpha=alpha;source.originalWidth=ow;source.originalHeight=oh;return source;
    }
    static ImagePayload.Prepared prepare(Context context,Uri uri,int budget,boolean png,Transport.Progress progress)throws Exception{Source source=load(context,uri);Transport.Image im=source.image;if(png){Crypto.check();byte[]data=PngWriter.encode(im,source.alpha);if(data.length>budget){int side=DenseTransport.squareRequired(data.length);throw Crypto.error(String.format(java.util.Locale.CHINA,"PNG无损需要%.1f KiB，底图可用%.1f KiB。%s不会继续缩小或降低画质。",data.length/1024.,budget/1024.,side>0?"建议方形底图至少"+side+"×"+side+"像素。":"请换更大底图或改用JPG。"));}return new ImagePayload.Prepared(data,im.width,im.height,0,true,source.originalWidth,source.originalHeight);}
        int[]pixels=im.pixels.clone();for(int i=0;i<pixels.length;i++){int p=pixels[i],a=p>>>24;if(a!=255){int r=((p>>16&255)*a+255*(255-a)+127)/255,g=((p>>8&255)*a+255*(255-a)+127)/255,b=((p&255)*a+255*(255-a)+127)/255;pixels[i]=0xff000000|(r<<16)|(g<<8)|b;}}
        Bitmap bitmap=Bitmap.createBitmap(pixels,im.width,im.height,Bitmap.Config.ARGB_8888);try{while(true){for(int quality=85;quality>=50;quality-=5){Crypto.check();if(progress!=null)progress.update(1,"正在压缩图片："+bitmap.getWidth()+"×"+bitmap.getHeight());ByteArrayOutputStream out=new ByteArrayOutputStream();if(!bitmap.compress(Bitmap.CompressFormat.JPEG,quality,out))throw Crypto.error("无法生成JPG图片。");byte[]data=out.toByteArray();if(data.length<=Math.min(budget,ImagePayload.MAX_JPEG))return new ImagePayload.Prepared(data,bitmap.getWidth(),bitmap.getHeight(),quality,false,source.originalWidth,source.originalHeight);}int w=Math.max(1,(int)(bitmap.getWidth()*.85)),h=Math.max(1,(int)(bitmap.getHeight()*.85));if(w==bitmap.getWidth()&&h==bitmap.getHeight())throw Crypto.error("图片无法压缩到当前底图容量，请换更大的底图。");Bitmap next=Bitmap.createScaledBitmap(bitmap,w,h,true);bitmap.recycle();bitmap=next;}}finally{bitmap.recycle();}}
    static Bitmap preview(Transport.Image image){return Images.thumbnail(image);}
    static Bitmap payloadPreview(ImagePayload.Prepared image){BitmapFactory.Options opt=new BitmapFactory.Options();opt.inPreferredConfig=Bitmap.Config.ARGB_8888;opt.inScaled=false;opt.inSampleSize=Math.max(1,Math.max(image.width/640,image.height/360));Bitmap bitmap=BitmapFactory.decodeByteArray(image.data,0,image.data.length,opt);if(bitmap==null)throw Crypto.error("图片正文无法解码。");return bitmap;}
    static void validate(ImagePayload.Prepared p){BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(p.data,0,p.data.length,opt);if(opt.outWidth!=p.width||opt.outHeight!=p.height)throw Crypto.error("图片正文尺寸无效。");Bitmap decoded=BitmapFactory.decodeByteArray(p.data,0,p.data.length);if(decoded==null)throw Crypto.error("图片正文已损坏。");decoded.recycle();}
}
